#==================================================================================
# * 0.1|e| Recombination Energetics in 4Au/TiO2 Structure *
# * Script was generated by Drew M. Glenna !!! *
#==================================================================================
import numpy as np
from ase.io import read, write
from ase.visualize import view
from ase.dft.kpoints import monkhorst_pack
from gpaw import GPAW, restart, FermiDirac, Davidson, MixerDif
from gpaw.cdft.cdft import CDFT
from gpaw.cdft.cdft_coupling import CouplingParameters

# =================================================================================
# Import initial structure
# =================================================================================
sys = read("i0.vasp")                                    # import initial structure

# =================================================================================
# Set up calculations
# =================================================================================
sys.set_pbc(True)                            # initial periodic boundary conditions
kp = monkhorst_pack((1, 1, 1))                                       # k-point grid
total_magmom = 0.0                                  # set the total magnetic moment
sys.set_initial_magnetic_moments([total_magmom / len(sys)] * len(sys))    # initial
fp1 = 'Ei.txt'                                           # make an Energy .txt file
fp2 = 'DCi.txt'                                          # make an Energy .txt file

# =================================================================================
# Set up initial geometric state calculations
# =================================================================================
# initial state 1 scf calculator
dfti1 = GPAW(
    gpts=(64, 48, 152),                                  # grid spacing in Angstrom
    mode='fd',                                             # finite difference mode
    charge=0,                                          # total charge of the system
    xc='PBE0',                                    # exchange correlation functional
    kpts=kp,                                                     # set k-point grid
    symmetry='off',                                    # set symmetry of the system
    occupations=FermiDirac(0.1, fixmagmom=False),                 # smearing method
    setups='paw',                                                    # PAW datasets
    eigensolver=Davidson(3),          # eigensolver with diagonalization iterations
    spinpol=True,                                      # spin-polarized calculation
    mixer=MixerDif(beta=0.01,                           # linear mixing coefficient
                   nmaxold=1,                               # of old densities used
                   weight=100.0,                            # density mixing weight
                   beta_m=0.01,                # linear magnetic mixing coefficient
                   nmaxold_m=8,                    # of old magnetic densities used
                   weight_m=100.0),                # magnetic density mixing weight
    maxiter=1000,                        # Set the maximum number of SCF iterations
    txt=f'i1.txt',                                               # output .txt file
    convergence={                                            # convergence criteria
        'eigenstates': 4.0e-8,                                    # eV^2 / electron
        'density': 1.0e-4,                                   # electrons / electron
        'energy': 1.0e-6})                                          # eV / electron

# initial state 1 cDFT calculator
Vc=[0.0]                                                     # initial guess for Vc
b=[4.0]                                                                 # Vc bounds
bound=[(ii-b[cc], ii+b[cc]) for cc, ii in enumerate(Vc)]         # set bounds on Vc
cdfti1 = CDFT(
    calc=dfti1,
    atoms=sys,
    charge_regions=[[72, 73, 74, 75]],                  # set Au constrained region
    charges=[0],                          # constrain 0 and 0 charge in Au and TiO2
    charge_coefs=Vc,                                         # initial guess for Vc
    bounds=bound,                                                       # Vc bounds
    method='L-BFGS-B',                                     # Vc optimization method
    txt=f'i1.cdft',                                              # cDFT output file
    forces='fd',
    tol=1e-6,
    minimizer_options={'gtol': 0.01})                   # charge tolerance for cdft

# Get initial state 1 dft energy
sys.calc = cdfti1
cdft_i1 = sys.get_potential_energy()

# initial state 2 scf calculator
dfti2 = GPAW(
    gpts=(64, 48, 152),                                  # grid spacing in Angstrom
    mode='fd',                                             # finite difference mode
    charge=0,                                          # total charge of the system
    xc='PBE0',                                    # exchange correlation functional
    kpts=kp,                                                     # set k-point grid
    symmetry='off',                                    # set symmetry of the system
    occupations=FermiDirac(0.1, fixmagmom=False),                 # smearing method
    setups='paw',                                                    # PAW datasets
    eigensolver=Davidson(3),          # eigensolver with diagonalization iterations
    spinpol=True,                                      # spin-polarized calculation
    mixer=MixerDif(beta=0.01,                           # linear mixing coefficient
                   nmaxold=1,                               # of old densities used
                   weight=100.0,                            # density mixing weight
                   beta_m=0.01,                # linear magnetic mixing coefficient
                   nmaxold_m=8,                    # of old magnetic densities used
                   weight_m=100.0),                # magnetic density mixing weight
    maxiter=1000,                        # Set the maximum number of SCF iterations
    txt=f'i2.txt',                                               # output .txt file
    convergence={                                            # convergence criteria
        'eigenstates': 4.0e-8,                                    # eV^2 / electron
        'density': 1.0e-4,                                   # electrons / electron
        'energy': 1.0e-6})                                          # eV / electron

# initial state 2 cDFT calculator
Vc=[0.0]                                                     # initial guess for Vc
b=[4.0]                                                                 # Vc bounds
bound=[(ii-b[cc], ii+b[cc]) for cc, ii in enumerate(Vc)]         # set bounds on Vc
cdfti2 = CDFT(
    calc=dfti2,
    atoms=sys,
    charge_regions=[[72, 73, 74, 75]],                  # set Au constrained region
    charges=[0.1],                  # constrain +0.1 and -0.1 charge in Au and TiO2
    charge_coefs=Vc,                                         # initial guess for Vc
    bounds=bound,                                                       # Vc bounds
    method='L-BFGS-B',                                     # Vc optimization method
    txt=f'i2.cdft',                                              # cDFT output file
    forces='fd',
    tol=1e-6,
    minimizer_options={'gtol': 0.01})                   # charge tolerance for cdft

# Get initial state 2 cdft energy
sys.calc = cdfti2
cdft_i2 = sys.get_potential_energy()

# Write to Energy file
with open(fp1, 'w') as file:
    # Write content to the file
    file.write(f"cdft_i1 = {cdft_i1} eV\n")
    file.write(f"cdft_i2 = {cdft_i2} eV\n")

# Calculate the diabatic coupling
coupling = CouplingParameters(cdft_a=cdfti1, 
                              cdft_b=cdfti2,
                              calc_gs=dfti1, 
                              AE=False)                       # use pseudo orbitals
Hab      = coupling.get_migliore_coupling()        # diabatic coupling from overlap

# Write to Diabatic Coupling file
with open(fp2, 'w') as file:
    # Write content to the file
    file.write(f"Hab = {Hab} eV\n")
#==================================================================================
